CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users, kind text NOT NULL, title text NOT NULL, body text NOT NULL DEFAULT '', entity_id text, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notifications_user ON notifications(user_id, created_at DESC);
CREATE TABLE notification_preferences(user_id uuid PRIMARY KEY REFERENCES users, in_app boolean NOT NULL DEFAULT true, push boolean NOT NULL DEFAULT false, email boolean NOT NULL DEFAULT false, quiet_start text NOT NULL DEFAULT '22:00', quiet_end text NOT NULL DEFAULT '07:00', critical_override boolean NOT NULL DEFAULT false, weekly boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE imports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users, filename text NOT NULL, source_hash text NOT NULL, original bytea NOT NULL, rows jsonb NOT NULL, state text NOT NULL DEFAULT 'preview' CHECK(state IN ('preview','completed')), report jsonb, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE imported_records(source_key text PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks, import_id uuid NOT NULL REFERENCES imports);
CREATE TABLE reporting_jobs(key text PRIMARY KEY, completed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ai_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users, state text NOT NULL CHECK(state IN ('reserved','completed','failed')), reserved_units integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
